insert into public.exercise_translations_gymtrack (exercisedb_id, name_pt, instructions_pt) values
  ('vrhHa6D', 'Puxada alta com pegada neutra fechada com apoio', array['Ajuste a máquina para o peso e a altura desejados', 'Posicione as mãos nas barras paralelas com uma pegada fechada e palmas viradas uma para a outra', 'Comece em uma suspensão controlada com os ombros ativos e não relaxados', 'Puxe os cotovelos para baixo e aproxime a parte superior do peito da barra sem chutar as pernas', 'Evite balançar as pernas para passar da barra', 'Desça até esticar os braços sem despencar do topo']),
  ('vsMcDi9', 'Rosca concentrada em pé com barra', array['Fique em pé com os pés na largura dos ombros e segure uma barra com uma mão e a palma voltada para cima', 'Apoie a outra mão na coxa para dar suporte', 'Posicione os ombros e os braços antes de flexionar os cotovelos', 'Flexione os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco', 'Mantenha o tronco parado e deixe a flexão do cotovelo erguer o peso', 'Desça até que os cotovelos estejam quase retos, mantendo a parte superior dos braços imóvel']),
  ('VsopqcV', 'Flexão com pegada fechada', array['Comece em uma posição de prancha alta com as mãos bem próximas, diretamente sob os ombros', 'Contraia o tronco e abaixe o corpo em direção ao chão, mantendo os cotovelos perto das costelas', 'Contraia o abdômen e os glúteos para que ombros, quadris e tornozelos se movam juntos', 'Flexione os cotovelos para baixar o peito mantendo o corpo em linha reta', 'Mantenha a cabeça alinhada com a coluna enquanto os cotovelos dobram', 'Empurre de volta até esticar os braços, mantendo a linha do corpo intacta']),
  ('vsVoPHt', 'Supino declinado na máquina', array['Ajuste a altura do assento e do encosto da máquina articulada em uma posição confortável', 'Sente-se na máquina com as costas apoiadas no encosto e os pés no chão', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou os puxadores mantendo o tronco firme', 'Mantenha os punhos alinhados e use um movimento natural para os ombros', 'Desça o peso até a altura inicial de forma controlada antes de empurrar novamente']),
  ('VtTbiP3', 'Puxada de quadril com elástico', array['Prenda um elástico de resistência em um ponto fixo firme na altura do solo', 'Fique de costas para o ponto de ancoragem em uma base estável com os pés na largura dos ombros', 'Destrave os joelhos e contraia o abdômen antes de mover os quadris para trás', 'Empurre os quadris para trás mantendo a carga próxima e a coluna firme', 'Controle o elástico na volta em vez de deixar que ele puxe você rapidamente', 'Empurre os quadris para a frente para ficar totalmente em pé sem inclinar para trás no topo']),
  ('vtusOWT', 'Supino no chão com barra e um braço', array['Deite-se de costas no chão com os joelhos flexionados e os pés apoiados', 'Segure a barra com uma mão, palma voltada para cima, e estenda o braço para cima sobre o peito', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou os puxadores mantendo o tronco firme', 'Mantenha ambos os ombros nivelados e evite virar o corpo para o lado do braço que trabalha', 'Desça o peso até a altura inicial de forma controlada antes de empurrar novamente e troque de lado quando necessário']),
  ('VuoerH0', 'Mergulho para tríceps no banco com as pernas estendidas', array['Sente-se na borda de um banco com as mãos segurando a borda e os dedos apontados para a frente.', 'Dê um passo à frente com os pés, deslize o quadril para fora do banco e estique os braços.', 'Abaixe os ombros e mantenha os cotovelos apontados principalmente para trás.', 'Flexione os cotovelos para descer entre os apoios e pare em uma profundidade confortável para os ombros.', 'Escolha uma profundidade que permita que os ombros fiquem confortáveis.', 'Pressione pelas mãos para subir e, em seguida, ajuste os ombros antes de outra repetição.']),
  ('vUTfFHw', 'Rosca de punho com elástico', array['Sente-se em um banco ou cadeira com os pés apoiados no chão.', 'Segure o elástico com ambas as mãos, com as palmas voltadas para cima, e apoie os antebraços nas coxas.', 'Mantenha os cotovelos relaxados para que os pequenos músculos da mão ou do antebraço absorvam a carga.', 'Movimente os punhos ou dedos enquanto os antebraços permanecem apoiados e imóveis.', 'Controle o elástico na volta em vez de deixar que ele puxe você de volta abruptamente.', 'Retorne suavemente ao início sem deixar a carga escapar das suas mãos.']),
  ('vvNjDJS', 'Tríceps coice com cabos e dois braços', array['Fique em pé com os pés na largura dos ombros e os joelhos levemente flexionados.', 'Segure o puxador do cabo em cada mão com as palmas voltadas para dentro e os braços flexionados a 90 graus.', 'Posicione os braços firmemente antes de estender os cotovelos.', 'Mantenha o braço ao lado do tronco e estique o cotovelo para trás.', 'Mantenha os braços firmes enquanto os antebraços se movimentam.', 'Flexione os cotovelos lentamente para retornar ao início da próxima repetição.']),
  ('Vvwjz6N', 'Flexão nordica reversa', array['Ajuste a máquina de flexão nórdica reversa para o seu corpo.', 'Posicione-se de bruços na máquina com os tornozelos fixados.', 'Alinhe os joelhos com a borda da máquina ou do banco antes de iniciar a flexão.', 'Flexione os joelhos para puxar o apoio em sua direção sem levantar o quadril do suporte.', 'Mantenha o quadril imóvel enquanto os joelhos flexionam.', 'Retorne pelo mesmo caminho em um ritmo controlado.']),
  ('VW88JNd', 'Elevação de panturrilha sentada unilateral com halteres e palma para cima', array['Sente-se em um banco ou cadeira com a coluna reta e os pés apoiados no chão.', 'Pegue um halter em uma mão e apoie-o sobre a coxa, com a palma voltada para cima.', 'Deixe os tornozelos se moverem livremente enquanto o resto do corpo permanece imóvel.', 'Suba na ponta dos pés, elevando os calcanhares o mais alto possível sem balançar.', 'Mantenha a pelve nivelada enquanto a perna de apoio faz o trabalho.', 'Abaixe os calcanhares em um ritmo compassado antes de subir novamente; alterne os lados quando necessário.']),
  ('VX5YKR5', 'Elevação de pernas deitada com auxílio e rebatida', array['Deite-se de costas com as pernas estendidas e os braços ao lado do corpo.', 'Coloque as mãos sob os glúteos para obter suporte.', 'Contraia o abdômen e mantenha os ombros ancorados ao suporte.', 'Eleve as pernas contraindo o tronco e movimentando o quadril em vez de balançar.', 'Desacelere as pernas antes que elas tirem a lombar da posição correta.', 'Abaixe as pernas lentamente sem balançar ou perder a posição do tronco.']),
  ('vYk8lqw', 'Crucifixo invertido inclinado com halteres', array['Ajuste o banco para aproximadamente 45 graus.', 'Sente-se no banco com o peito apoiado no encosto e segure um halter em cada mão.', 'Comece com uma carga gerenciável e uma leve flexão nos cotovelos.', 'Eleve os braços para os lados até a altura dos ombros, sem inclinar o tronco ou encolher os ombros.', 'Pare perto da altura dos ombros em vez de encolher os ombros para subir mais.', 'Abaixe os braços lentamente para as laterais sem balançar o peso.']),
  ('VYmYxK5', 'Desenvolvimento com pegada neutra e um braço com halter na bola suíça', array['Sente-se em uma bola suíça com os pés apoiados e a coluna reta.', 'Pegue um halter em uma mão com a palma voltada para dentro e o cotovelo flexionado a 90 graus.', 'Contraia o tronco e alinhe os punhos com os antebraços.', 'Pressione o peso para cima enquanto mantém o tronco contraído.', 'Mantenha ambos os ombros nivelados e evite girar em direção ao braço que está trabalhando.', 'Abaixe o peso até a altura inicial de forma controlada antes de empurrar novamente; alterne os lados quando necessário.']),
  ('vzAxBtt', 'Desenvolvimento com um braço com kettlebell', array['Fique em pé com os pés na largura dos ombros, segurando um kettlebell em uma mão com as palmas para baixo.', 'Antes de se mover, flexione levemente os joelhos e incline o quadril, abaixando o kettlebell entre as pernas.', 'Contraia o abdômen antes de puxar e mantenha a carga próxima ao corpo.', 'Empurre com as pernas e o quadril, depois guie o peso até a posição de recebimento.', 'Mantenha ambos os ombros nivelados e evite girar em direção ao braço de trabalho.', 'Fique totalmente em pé para finalizar, depois abaixe o peso de forma controlada antes da próxima repetição; alterne os lados quando a série exigir.']),
  ('w1NOByi', 'Remada com banda elástica no agachamento', array['Conecte a banda a um ponto de ancoragem firme na altura da cintura.', 'Fique de frente para o ponto de ancoragem em uma base estável com os pés na largura dos ombros.', 'Contraia o abdômen e distribua a pressão por todo o pé.', 'Flexione o quadril e os joelhos para abaixar, mantendo os pés apoiados e os joelhos alinhados com os dedos dos pés.', 'Controle a banda no retorno em vez de deixar que ela puxe você de volta.', 'Fique totalmente em pé, ajuste sua postura e respiração, depois inicie a próxima descida.']),
  ('W1p7BND', 'Alongamento de peito com bola suíça', array['Sente-se na bola suíça com os pés apoiados e as costas retas.', 'Segure a bola suíça com ambas as mãos e estenda os braços para a frente.', 'Estabeleça a posição inicial e respire calmamente antes de aprofundar o movimento.', 'Avance em direção ao alongamento até sentir uma tensão leve; continue respirando e evite balançar.', 'Mantenha a bola firme e use os pés para controlar o equilíbrio.', 'Mantenha a posição com respiração constante, depois solte suavemente; repita do outro lado, se necessário.']),
  ('w2oRpuH', 'Remada sentada com pegada estreita alternada na máquina', array['Ajuste a altura do assento e a posição da plataforma para garantir o alinhamento adequado.', 'Sente-se na máquina com as costas retas e os pés apoiados na plataforma.', 'Posicione o tronco e permita que os braços se estendam para a frente sem curvar excessivamente.', 'Puxe os cotovelos para trás e traga o puxador ou o peso em direção ao tronco.', 'Finalize o movimento de um lado antes que o outro lado comece.', 'Estenda os braços para a frente novamente sem deixar o tronco balançar; alterne os lados quando a série exigir.']),
  ('W31mMjd', 'Agachamento búlgaro lateral com barra', array['Fique em pé com os pés mais afastados que a largura dos ombros, com as pontas dos pés viradas levemente para fora.', 'Posicione uma barra na parte superior das costas, apoiando-a nos trapézios.', 'Contraia o abdômen e distribua a pressão por todo o pé.', 'Flexione o quadril e os joelhos para abaixar, mantendo os pés apoiados e os joelhos alinhados com os dedos dos pés.', 'Empurre para cima elevando o peito e o quadril juntos; impeça que os joelhos desabem para dentro.', 'Fique totalmente em pé, ajuste sua postura e respiração, depois inicie a próxima descida.']),
  ('w44vFvP', 'Remada unilateral no Smith', array['Ajuste a altura da barra do Smith na altura da cintura.', 'Fique de frente para o Smith em uma base estável com os pés na largura dos ombros.', 'Posicione o tronco e permita que os braços se estendam para a frente sem curvar excessivamente.', 'Puxe os cotovelos para trás e traga o puxador ou o peso em direção ao tronco.', 'Mantenha ambos os ombros nivelados e evite girar em direção ao braço de trabalho.', 'Estenda os braços para a frente novamente sem deixar o tronco balançar; alterne os lados quando a série exigir.']),
  ('w4dLzSx', 'Crucifixo declinado unilateral no cabo', array['Conecte um puxador D a uma polia baixa e ajuste o banco para um ângulo declinado.', 'Deite-se no banco com a cabeça voltada para a máquina e segure o puxador com a mão direita.', 'Mantenha uma leve flexão nos cotovelos e posicione os ombros antes de mover os braços.', 'Com uma leve flexão nos cotovelos, junte os braços em um arco amplo.', 'Mantenha ambos os ombros nivelados e evite girar em direção ao braço de trabalho.', 'Abra os braços de volta pelo mesmo arco sem deixar a carga cair; alterne os lados quando a série exigir.']),
  ('W6PxUkg', 'Tríceps coice com halteres', array['Fique em pé com os pés na largura dos ombros e segure um halter em cada mão.', 'Flexione levemente os joelhos e incline o tronco para a frente a partir do quadril, mantendo a coluna firme.', 'Posicione os braços no alto antes de estender os cotovelos.', 'Mantenha a parte superior do braço junto ao tronco e estique o cotovelo para trás.', 'Mantenha os braços firmes enquanto os antebraços se movimentam.', 'Flexione os cotovelos lentamente para retornar ao início da próxima repetição.']),
  ('w7obpWd', 'Tríceps com polia', array['Conecte uma barra reta a uma máquina de cabo com polia alta.', 'Fique de frente para a máquina com os pés na largura dos ombros e uma leve flexão nos joelhos.', 'Afaste-se o suficiente da pilha de pesos para que o cabo fique tenso.', 'Mantenha os cotovelos próximos às costelas e estenda os braços contra o cabo.', 'Mantenha os cotovelos perto do corpo em vez de deixar os ombros balançarem.', 'Retorne suavemente ao início antes de repetir.']),
  ('W7yh3Yo', 'Tríceps francês unilateral com halter na bola suíça', array['Sente-se em uma bola suíça com os pés apoiados e as costas retas.', 'Pegue um halter em uma mão com a palma virada para cima e o cotovelo dobrado a um ângulo de 90 graus.', 'Posicione os braços firmemente antes de estender os cotovelos.', 'Dobre os cotovelos para abaixar a barra atrás da cabeça enquanto os braços permanecem praticamente parados.', 'Mantenha ambos os ombros nivelados e evite girar em direção ao braço que está trabalhando.', 'Estenda os cotovelos para levar a barra acima da cabeça, depois inicie a próxima repetição controlada; troque de lado quando a série exigir.']),
  ('W8KAlkI', 'Flexão com bola medicinal', array['Comece em uma posição de prancha alta com as mãos na bola medicinal, na largura dos ombros.', 'Contraia o tronco e abaixe o corpo em direção ao chão dobrando os cotovelos, com a coluna firme.', 'Contraia o abdômen e os glúteos para que ombros, quadris e tornozelos se movam juntos.', 'Dobre os cotovelos para abaixar o peito enquanto mantém o corpo em linha reta.', 'Mantenha a cabeça alinhada com a coluna enquanto os cotovelos dobram.', 'Empurre de volta para cima com os braços estendidos, mantendo a linha do corpo intacta.']),
  ('W9pFVv1', 'Agachamento com barra', array['Prepare uma barra em um suporte de agachamento na altura do peito.', 'Fique de costas para o suporte, com uma postura estável e os pés na largura dos ombros.', 'Contraia o abdômen e distribua a pressão por todo o pé.', 'Dobre os quadris e os joelhos para abaixar, mantendo os pés apoiados e os joelhos alinhados com os dedos dos pés.', 'Empurre para cima com o peito e os quadris subindo juntos; evite que os joelhos desabem para dentro.', 'Fique totalmente em pé, ajuste sua base e respiração, depois inicie a próxima descida.']),
  ('WbNq5Xu', 'Supino sentado na máquina', array['Ajuste o assento ao seu corpo, depois acomode-se na máquina.', 'Segure as manoplas com as palmas voltadas para baixo e posicione as mãos na altura do peito.', 'Contraia o tronco e alinhe os punhos com os antebraços.', 'Empurre o peso ou as manoplas para longe enquanto mantém o tronco contraído.', 'Mantenha os punhos alinhados e use uma trajetória de ombro que pareça natural.', 'Abaixe o peso até a altura inicial de forma controlada antes de empurrar novamente.']),
  ('wbUYILZ', 'Elevação de cotovelo - flexão reversa', array['Comece deitado de bruços no chão com as pernas estendidas e as mãos posicionadas diretamente debaixo dos ombros.', 'Contraia o tronco e empurre com as palmas das mãos para levantar a parte superior do corpo do chão, mantendo os cotovelos próximos aos lados.', 'Contraia o abdômen e os glúteos para que ombros, quadris e tornozelos se movam juntos.', 'Dobre os cotovelos para abaixar o peito enquanto mantém o corpo em linha reta.', 'Mantenha a cabeça alinhada com a coluna enquanto os cotovelos dobram.', 'Empurre de volta para cima com os braços estendidos, mantendo a linha do corpo intacta.']),
  ('WCAvOfC', 'Toque no pé lateral', array['Fique de pé com os pés na largura dos ombros e os braços estendidos para os lados.', 'Incline-se para a direita na cintura, alcançando o pé direito com a mão direita enquanto mantém a mão esquerda estendida para o lado.', 'Flexione levemente os joelhos e deixe os quadris iniciarem o movimento.', 'Dobre-se para a frente a partir dos quadris e deixe suas mãos irem em direção aos pés sem forçar o alcance.', 'Mantenha o movimento controlado durante toda a amplitude.', 'Retorne pelo mesmo caminho em um ritmo controlado.']),
  ('WcHl7ru', 'Supino com pegada fechada no Smith', array['Ajuste o assento ao seu corpo, depois acomode-se na máquina.', 'Segure a barra com uma pegada fechada, um pouco mais estreita que a largura dos ombros.', 'Contraia o tronco e alinhe os punhos com os antebraços.', 'Empurre o peso ou as manoplas para longe enquanto mantém o tronco contraído.', 'Mantenha os punhos alinhados e use uma trajetória de ombro que pareça natural.', 'Abaixe o peso até a altura inicial de forma controlada antes de empurrar novamente.']),
  ('wd4ds3s', 'Remada em pé com peso corporal', array['Fique em pé com os pés na largura dos ombros e joelhos levemente flexionados', 'Segure uma barra ou pegadores com as palmas voltadas para baixo', 'Posicione o tronco e estenda os braços para frente sem curvar excessivamente', 'Puxe os cotovelos para trás e leve o pegador ou peso em direção ao tronco', 'Traga os cotovelos para trás sem dar trancos no tronco', 'Estenda os braços para frente novamente sem deixar o tronco balançar']),
  ('wDN97Ca', 'Supino na máquina para peitoral interno', array['Ajuste o assento ao seu corpo e acomode-se na máquina', 'Segure os pegadores com as palmas voltadas para baixo e posicione os cotovelos em um ângulo de 90 graus', 'Estabilize o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou os pegadores mantendo o tronco firme', 'Mantenha os punhos alinhados e use uma trajetória de ombro que pareça natural', 'Abaixe o peso até a altura inicial de forma controlada antes de empurrar novamente']),
  ('wdRZISl', 'Desenvolvimento militar em pé com barra e pegada fechada', array['Fique em pé com os pés na largura dos ombros e segure a barra com as palmas voltadas para baixo, mãos ligeiramente mais próximas que a largura dos ombros', 'Antes de se mover, levante a barra até a altura dos ombros, mantendo os cotovelos próximos ao corpo', 'Estabilize o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou os pegadores mantendo o tronco firme', 'Mantenha os punhos alinhados e use uma trajetória de ombro que pareça natural', 'Abaixe o peso até a altura inicial de forma controlada antes de empurrar novamente']),
  ('wDUqY2u', 'Rosca bíceps no cabo por cima', array['Conecte uma barra reta a um aparelho de cabo com polia alta', 'Fique de frente para a máquina em uma base estável com os pés na largura dos ombros', 'Posicione os ombros e os braços antes de flexionar os cotovelos', 'Flexione os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco', 'Mantenha o tronco firme e deixe a flexão do cotovelo levantar o peso', 'Abaixe até que os cotovelos estejam quase retos, mantendo a parte superior dos braços imóvel']),
  ('weoDEpH', 'Elevação de pernas na barra fixa paralela', array['Sente-se na cadeira capitão com as costas apoiadas no encosto e os antebraços apoiados nas almofadas', 'Mantenha o tronco estável e as costas retas', 'Contraia o abdômen e mantenha os ombros ancorados no suporte', 'Eleve as pernas contraindo o tronco e movendo-se a partir dos quadris, em vez de balançar', 'Desacelere as pernas antes que elas tirem a parte inferior das costas da posição', 'Abaixe as pernas lentamente sem balançar ou perder a posição do tronco']),
  ('wEulIzp', 'Elevação lateral com um braço no cabo', array['Fique em pé com os pés na largura dos ombros, de frente para a máquina de cabo', 'Segure a manopla do cabo com uma mão, palma voltada para baixo, e afaste-se o suficiente da máquina para haver tensão no cabo', 'Comece com uma carga gerenciável e uma leve flexão nos cotovelos', 'Eleve os braços para os lados até a altura dos ombros sem inclinar ou encolher os ombros', 'Mantenha ambos os ombros nivelados e resista em girar em direção ao braço que está trabalhando', 'Abaixe os braços lentamente para os lados sem balançar o peso; troque de lado quando a série exigir']),
  ('wf24o8S', 'Remada com dois kettlebells', array['Fique em pé com os pés na largura dos ombros, joelhos levemente flexionados, e segure um kettlebell em cada mão com as palmas voltadas para o corpo', 'Incline-se para frente a partir dos quadris, com a coluna firme e o core ativado', 'Posicione o tronco e estenda os braços para frente sem curvar excessivamente', 'Puxe os cotovelos para trás e leve o pegador ou peso em direção ao tronco', 'Traga os cotovelos para trás sem dar trancos no tronco', 'Estenda os braços para frente novamente sem deixar o tronco balançar']),
  ('wfotm7S', 'Salto em profundidade com agachamento com peso corporal', array['Fique em pé e ajuste os pés na largura dos ombros', 'Antes de se mover, abaixe o corpo em uma posição de agachamento flexionando os joelhos e empurrando os quadris para trás', 'Contraia o abdômen e distribua a pressão por todo o pé', 'Flexione nos quadris e joelhos para abaixar, mantendo os pés apoiados no chão e os joelhos alinhados com os dedos dos pés', 'Empurre para cima com o peito e os quadris subindo juntos; evite que os joelhos desabem para dentro', 'Fique totalmente em pé, ajuste sua postura e respiração, depois inicie a próxima descida']),
  ('WFucoe6', 'Elevação de pernas e quadril com torção na barra fixa', array['Suspenda-se em uma barra fixa com os braços esticados e as pernas esticadas', 'Contraia o tronco e levante as pernas em direção ao peito, mantendo-as esticadas', 'Apoie os pés e evite expandir as costelas enquanto o quadril se prepara para subir', 'Pressione com os pés e eleve o quadril até que o tronco e as coxas fiquem alinhados', 'Pare quando o quadril estiver alinhado com o tronco; não arqueie mais a parte inferior das costas', 'Abaixe o quadril de forma constante e mantenha os pés apoiados para a próxima repetição']),
  ('Wgaz7pm', 'Abdominal sentado na máquina', array['Sente-se na máquina articulada com as costas apoiadas no encosto e os pés apoiados', 'Segure nos puxadores ou coloque as mãos nos suportes laterais para apoio', 'Posicione a pelve e mantenha o pescoço relaxado antes de fazer a flexão para cima', 'Enrole a caixa torácica em direção à pelve, permitindo que o abdômen movimente o tronco', 'Deixe um pequeno espaço entre o queixo e o peito; mantenha o movimento no tronco', 'Abaixe os ombros ou o tronco com controle antes da próxima repetição']),
  ('Wgbn9qo', 'Mergulho para tríceps (entre bancos)', array['Sente-se em um banco com as mãos segurando a borda do banco e os dedos apontados para a frente', 'Retire o quadril do banco, sustentando seu peso com as mãos', 'Posicione os ombros para baixo e mantenha os cotovelos apontados principalmente para trás', 'Flexione os cotovelos para descer entre os apoios; pare em uma profundidade confortável para os ombros', 'Escolha uma profundidade que permita manter os ombros confortáveis', 'Pressione com as mãos para subir, depois ajuste os ombros antes de outra repetição']),
  ('WgJnBH5', 'Rosca bíceps sentado com halteres (na bola suíça)', array['Sente-se em uma bola suíça com os pés apoiados e as costas retas', 'Pegue um halter em cada mão com as palmas voltadas para a frente e os braços esticados', 'Posicione os ombros e a parte superior dos braços antes de flexionar os cotovelos', 'Flexione os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco', 'Mantenha a bola estável e use os pés para controlar o equilíbrio', 'Abaixe até que os braços estejam quase esticados, mantendo a parte superior dos braços imóvel']),
  ('WhuFnR7', 'Elevação de pernas deitado no banco reto', array['Deite-se em um banco reto com as costas pressionadas contra ele', 'Coloque as mãos sob os glúteos para dar suporte', 'Contraia o abdômen e mantenha os ombros fixos no apoio', 'Levante as pernas contraindo o tronco e movimentando o quadril em vez de balançar', 'Desacelere as pernas antes que elas tirem a parte inferior das costas da posição', 'Abaixe as pernas devagar sem balançar ou perder a posição do tronco']),
  ('wi2H9QX', 'Supino declinado com pegada aberta no Smith', array['Ajuste o banco declinado para o ângulo desejado', 'Posicione-se no banco com os pés presos sob os roletes', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou os puxadores mantendo o tronco contraído', 'Mantenha os punhos alinhados e use uma trajetória para os ombros que pareça natural', 'Abaixe o peso até a altura inicial com controle antes de empurrar novamente']),
  ('wigSg76', 'Flexão com palma', array['Comece em posição de prancha alta com as mãos logo além da largura dos ombros', 'Abaixe o corpo em direção ao chão flexionando os cotovelos, mantendo o core contraído', 'Contraia o abdômen e os glúteos para que ombros, quadris e tornozelos se movam juntos', 'Flexione os cotovelos para abaixar o peito mantendo o corpo em linha reta', 'Mantenha a cabeça alinhada com a coluna enquanto os cotovelos flexionam', 'Empurre de volta à extensão dos braços, mantendo a linha do corpo intacta']),
  ('wkgnGfb', 'Supino com pegada neutra e inclinado com halteres na bola de exercício', array['Sente-se em uma bola de exercício com um halter em cada mão, com as palmas voltadas uma para a outra', 'Dê um passo à frente com os pés e role o corpo pela bola até que sua cabeça, pescoço e parte superior das costas estejam apoiados na bola', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou os puxadores mantendo o tronco contraído', 'Mantenha a bola estável e use os pés para controlar o equilíbrio', 'Abaixe o peso até a altura inicial com controle antes de empurrar novamente']),
  ('WKMQzCD', 'Afundo com passagem de kettlebell', array['Fique em pé e posicione os pés na largura dos ombros, segurando um kettlebell na altura do peito com ambas as mãos', 'Dê um passo à frente com o pé direito, abaixando o corpo em uma posição de afundo', 'Defina sua base com largura suficiente para se equilibrar antes de flexionar qualquer um dos joelhos', 'Entre no movimento e flexione ambos os joelhos, mantendo o pé da frente apoiado', 'Mantenha o pé da frente apoiado e evite fechar o joelho para dentro', 'Empurre com o pé da frente para retornar ao início e depois troque as pernas conforme planejado']),
  ('WL4EmxJ', 'Abdução de quadril em ponte lateral', array['Posicione-se de lado com as pernas estendidas e empilhadas uma sobre a outra', 'Apoie-se no antebraço, mantendo o cotovelo diretamente abaixo do ombro', 'Contraia o abdômen e encontre uma posição que consiga manter sem prender a respiração', 'Mantenha a linha da prancha lateral e eleve a perna de cima sem deixar o quadril girar para trás', 'Continue respirando de forma constante enquanto mantém a mesma linha corporal', 'Abaixe a perna sem deixar o quadril cair e repita antes de trocar de lado']),
  ('WLvTAv5', 'Rosca de biceps inclinada com barra de bruços', array['Ajuste o banco para aproximadamente 45 graus', 'Posicione-se de bruços no banco com o peito e o estômago apoiados nele', 'Posicione os ombros e os braços antes de flexionar os cotovelos', 'Flexione os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco', 'Mantenha o tronco firme e deixe a flexão do cotovelo levantar o peso', 'Abaixe até que os cotovelos estejam quase retos, mantendo os braços parados']),
  ('WM6TvvW', 'Remada baixa sentada no cabo', array['Sente-se na máquina com os pés apoiados e os joelhos levemente flexionados', 'Segure os puxadores com as palmas das mãos voltadas para baixo', 'Posicione o tronco e permita que os braços avancem sem arredondar excessivamente', 'Puxe os cotovelos para trás e traga o puxador ou peso em direção ao tronco', 'Puxe os cotovelos para trás sem dar trancos no tronco', 'Estenda os braços para frente novamente sem deixar o tronco despencar']),
  ('WME869U', 'Extensão de lombar na bola suíça com joelhos fora do chão', array['Coloque a bola suíça no chão e posicione-se de bruços sobre ela, com o quadril apoiado na bola e os pés contra uma parede para estabilidade', 'Coloque as mãos atrás da cabeça ou cruzadas sobre o peito', 'Fixe o quadril e os pés no apoio antes de elevar', 'Eleve o tronco ou as pernas até alinharem com o corpo, sem arquear acentuadamente a lombar', 'Mantenha a bola firme e use os pés para controlar o equilíbrio', 'Retorne o peso ou o corpo à posição inicial sem pressa']),
  ('wnEscH8', 'Abdominal com desenvolvimento com barra', array['Deite-se de costas em um colchonete com os joelhos flexionados e os pés apoiados', 'Segure a barra com as palmas voltadas para baixo, apoiando-a no peito', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou os puxadores para longe enquanto mantém o tronco contraído', 'Mantenha os punhos alinhados e use uma trajetória de ombro que pareça natural', 'Abaixe o peso até a altura inicial de forma controlada antes de empurrar novamente']),
  ('wOLmCXc', 'Rosca tríceps com halteres em apoio unipodal', array['Fique em pé, posicione os pés na largura dos ombros e segure um halter na mão direita', 'Flexione levemente os joelhos e incline o tronco à frente a partir do quadril, com a coluna firme', 'Posicione os braços antes de estender os cotovelos', 'Mantenha o braço ao lado do tronco e estique o cotovelo para trás', 'Mantenha os braços firmes enquanto os antebraços se movimentam', 'Flexione os cotovelos lentamente para retornar ao início da próxima repetição']),
  ('woLo1QN', 'Flexão inclinada (no caixote)', array['Apoie as mãos na borda de um caixote ou superfície elevada, logo acima da largura dos ombros', 'Estenda as pernas para trás, apoiando-se na ponta dos pés, criando uma linha reta da cabeça aos calcanhares', 'Contraia o abdômen e os glúteos para que ombros, quadris e tornozelos se movam juntos', 'Flexione os cotovelos para abaixar o peito, mantendo o corpo em linha reta', 'Mantenha a cabeça alinhada com a coluna enquanto os cotovelos dobram', 'Empurre de volta à extensão total dos braços, mantendo a linha do corpo intacta']),
  ('wpbD28t', 'Flexão lateral', array['Comece deitado de lado com as pernas estendidas e empilhadas uma sobre a outra', 'Posicione a mão de baixo no chão diretamente sob o ombro com os dedos apontando para a frente', 'Contraia o abdômen e os glúteos para que os ombros, quadris e tornozelos se movam juntos', 'Flexione os cotovelos para abaixar o peito mantendo o corpo em linha reta', 'Mantenha a cabeça alinhada com a coluna enquanto os cotovelos se flexionam', 'Empurre de volta à posição com os braços esticados mantendo a linha do corpo intacta']),
  ('wPypxFY', 'Flexão lateral com cabo', array['Fique em pé com os pés na largura dos ombros e segure o puxador do cabo com uma mão', 'Mantenha sua coluna em uma posição neutra confortável e o core ativado', 'Fique em pé ou sentado erguido com a pelve voltada para a frente', 'Incline-se para o lado pela cintura sem torcer ou deixar o quadril se deslocar', 'Deixe a lateral do tronco trabalhar sem torcer ou deslocar o quadril', 'Retorne o peso ou o corpo à posição inicial sem pressa']),
  ('wQ2c4XD', 'Stiff com barra', array['Fique em pé com os pés na largura dos ombros e os dedos apontados para a frente', 'Segure a barra com as palmas voltadas para baixo e as mãos logo acima da largura dos ombros', 'Destrave os joelhos e contraia o abdômen antes de mover o quadril para trás', 'Envie o quadril para trás com uma leve flexão nos joelhos abaixando a carga perto das pernas até sentir os posteriores de coxa', 'Mantenha o peso próximo às pernas e pare quando as costas começarem a arredondar', 'Empurre o quadril para frente para ficar em pé sem inclinar para trás no topo']),
  ('wqNPGCg', 'Remada alta no cabo para deltóide posterior (com corda)', array['Conecte um puxador de corda a uma máquina de polia baixa', 'Fique de frente para a máquina em uma base estável com os pés na largura dos ombros', 'Posicione o tronco e permita que os braços alcancem a frente sem arredondar excessivamente', 'Puxe os cotovelos para trás e leve o puxador ou peso em direção ao tronco', 'Traga os cotovelos para trás sem dar trancos no tronco', 'Estique os braços para a frente novamente sem deixar o tronco balançar']),
  ('WrYPP2g', 'Remada alta unilateral com cabo (ajoelhado)', array['Conecte um puxador a uma máquina de cabo na altura da cintura', 'Ajoelhe-se de frente para a máquina de cabo e segure o puxador com uma mão', 'Posicione o tronco e permita que os braços alcancem a frente sem arredondar excessivamente', 'Puxe os cotovelos para trás e leve o puxador ou peso em direção ao tronco', 'Mantenha ambos os ombros nivelados e resista a girar em direção ao braço que trabalha', 'Estique os braços para a frente novamente sem deixar o tronco balançar e alterne os lados quando necessário']),
  ('wSScovH', 'Extensão de quadril curvado com elástico', array['Fixe o elástico em um ponto de ancoragem sólido e baixo', 'Fique de costas para o ponto de ancoragem em uma base estável com os pés na largura dos ombros', 'Apoie bem os pés e impeça que as costelas se expandam enquanto o quadril se prepara para subir', 'Pressione através dos pés e eleve o quadril até que o tronco e as coxas fiquem alinhados', 'Controle o elástico na volta em vez de deixar que ele puxe você rapidamente', 'Abaixe o quadril de forma constante e mantenha os pés apoiados para o próximo movimento']),
  ('wt6rwjk', 'Remada curvada com rotação de palma com halteres', array['Fique em pé com os pés na largura dos ombros segurando um halter em cada mão com as palmas voltadas para baixo', 'Incline-se para a frente a partir do quadril com a coluna firme e os joelhos levemente flexionados', 'Posicione o tronco e permita que os braços alcancem a frente sem arredondar excessivamente', 'Puxe os cotovelos para trás e leve o puxador ou peso em direção ao tronco', 'Traga os cotovelos para trás sem dar trancos no tronco', 'Estique os braços para a frente novamente sem deixar o tronco balançar']),
  ('wu5LXwz', 'Extensão de tríceps com barra olímpica', array['Comece em pé com os pés na largura dos ombros segurando a barra com as palmas voltadas para baixo', 'Eleve a barra acima da cabeça esticando os braços', 'Posicione os braços firmemente antes de estender os cotovelos', 'Mantenha a parte superior dos braços firme e estenda através dos cotovelos para mover o peso', 'Mantenha a parte superior dos braços firme enquanto os antebraços se movimentam', 'Flexione os cotovelos lentamente para retornar ao início da próxima repetição']),
  ('WU9BLIs', 'Russian twist com peso (pernas para cima)', array['Sente-se no chão com os joelhos flexionados e os pés retirados do chão, mantendo as pernas juntas.', 'Segure o peso com ambas as mãos à frente do peito, mantendo os cotovelos relaxados.', 'Fixe a pelve e faça a rotação através da caixa torácica.', 'Gire o tronco enquanto os quadris e a parte inferior do corpo permanecem o mais estáveis possível.', 'Mantenha a rotação suave em vez de lançar os braços pelo corpo.', 'Retorne pelo centro antes de girar para o outro lado.']),
  ('WVD66ff', 'Extensão de lombar na bola suíça com rotação', array['Comece deitado de bruços na bola suíça, com os quadris apoiados na bola e os pés firmemente apoiados no chão.', 'Posicione as mãos atrás da cabeça ou cruze-os sobre o peito.', 'Fixe os quadris e os pés no apoio antes de elevar.', 'Eleve o tronco ou as pernas até ficarem alinhados com o corpo, sem curvar excessivamente a parte inferior das costas.', 'Mantenha a bola estável e use os pés para controlar o equilíbrio.', 'Retorne suavemente ao início antes de repetir.']),
  ('wVompEp', 'Flexão no bosu', array['Posicione o bosu no chão com o lado plano voltado para cima.', 'Posicione-se em posição de flexão com as mãos nas bordas externas do bosu.', 'Contraia o abdômen e os glúteos para que ombros, quadris e tornozelos se movam juntos.', 'Flexione os cotovelos para abaixar o peito, mantendo o corpo em linha reta.', 'Mantenha a cabeça alinhada com a coluna enquanto os cotovelos flexionam.', 'Empurre de volta para os braços esticados, mantendo a linha do corpo intacta.']),
  ('WW95auq', 'Abdominal com cabo ajoelhado', array['Conecte uma alça de corda a uma polia alta e ajoelhe-se de costas para a máquina.', 'Segure a alça de corda com ambas as mãos e coloque-a atrás da cabeça, mantendo os cotovelos apontados para os lados.', 'Fixe a pelve e mantenha o pescoço relaxado antes de curvar para cima.', 'Curve sua caixa torácica em direção à pelve, permitindo que o abdômen mova o tronco.', 'Deixe um pequeno espaço entre o queixo e o peito; mantenha o movimento no tronco.', 'Abaixe os ombros ou o tronco com controle antes da próxima repetição.']),
  ('WWD6FzI', 'Leg press 45 graus unilateral', array['Ajuste a máquina de leg press para um ângulo de 45 graus.', 'Sente-se na máquina com as costas apoiadas no encosto e os pés na plataforma.', 'Apoie os pés firmemente na plataforma e mantenha os quadris contra o assento.', 'Flexione os joelhos para trazer a plataforma em sua direção e, em seguida, empurre-a com os pés.', 'Mantenha a pelve nivelada enquanto a perna de apoio faz o trabalho.', 'Retorne suavemente ao início antes de repetir; alterne os lados quando necessário.']),
  ('wWFspEi', 'Afundo búgaro no smith', array['Posicione-se em frente à máquina smith com os pés na largura dos ombros.', 'Coloque um pé atrás de você em um banco ou degrau, com os dedos apontados para a frente.', 'Contraia o abdômen e distribua a pressão por todo o pé.', 'Flexione os quadris e os joelhos para abaixar, mantendo os pés apoiados e os joelhos alinhados com os dedos.', 'Empurre para cima com o peito e os quadris subindo juntos; evite que os joelhos caiam para dentro.', 'Fique totalmente em pé, ajuste sua postura e respiração, e inicie a descida seguinte.']),
  ('wXvUZC8', 'Flexão com puxada corporal', array['Comece em posição de flexão com as mãos logo acima da largura dos ombros e o corpo em linha reta.', 'Abaixe o peito em direção ao chão flexionando os cotovelos, mantendo o corpo reto.', 'Contraia o abdômen e os glúteos para que ombros, quadris e tornozelos se movam juntos.', 'Flexione os cotovelos para abaixar o peito, mantendo o corpo em linha reta.', 'Mantenha a cabeça alinhada com a coluna enquanto os cotovelos flexionam.', 'Empurre de volta para os braços esticados, mantendo a linha do corpo intacta.']),
  ('wyaqzOS', 'Tríceps testa com halteres unilateral pronado', array['Acomode-se em um banco com as costas e a cabeça apoiadas, e os pés no chão.', 'Segure um halter em uma mão com a palma virada para baixo e estenda o braço para cima acima do ombro.', 'Fixe os braços na posição antes de estender os cotovelos.', 'Mantenha a parte superior dos braços firme e estenda pelos cotovelos para mover o peso.', 'Mantenha ambos os ombros nivelados e evite virar o corpo para o braço em trabalho.', 'Flexione os cotovelos lentamente para retornar ao início da próxima repetição; alterne os lados quando necessário.']),
  ('x0lwvfq', 'Tríceps Coice sentado com alteres alternado', array['Sente-se em um banco com um halter em cada mão, com as palmas voltadas para dentro', 'Incline-se para a frente na cintura, com a coluna firme e paralela ao solo', 'Posicione os braços antes de estender os cotovelos', 'Mantenha o braço ao lado do tronco e estique o cotovelo para trás', 'Conclua o movimento de um lado antes que o outro lado assuma', 'Dobre os cotovelos lentamente para retornar ao início da próxima repetição e alterne os lados quando a série exigir']),
  ('x2chWLO', 'Alongamento lateral do pescoço', array['Fique em pé ou sentado com os ombros relaxados', 'Incline a cabeça para um lado, trazendo a orelha em direção ao ombro', 'Estabeleça a posição inicial e respire calmamente antes de aprofundar', 'Aproxime-se do alongamento até sentir uma tensão leve, continue respirando e evite balançar', 'Mantenha um alongamento leve em vez de puxar mais com impulso', 'Mantenha a posição com respiração constante, solte com cuidado e repita do outro lado se necessário']),
  ('x306lCW', 'Rotação externa de ombro em pé com alteres', array['Fique em pé com os pés na largura dos ombros e segure um halter em cada mão com as palmas voltadas para o corpo', 'Levante os braços para os lados até ficarem paralelos ao chão, mantendo os cotovelos flexionados', 'Posicione a pelve e faça a rotação através da caixa torácica', 'Gire através do tronco enquanto os quadris e a parte inferior do corpo permanecem firmes conforme a configuração permitir', 'Mantenha a rotação suave em vez de jogar os braços através do corpo', 'Retorne pelo centro antes de girar para o outro lado']),
  ('X3cqyXz', 'Remada curvada na máquina', array['Fique em pé com os pés na largura dos ombros e os joelhos flexionados', 'Segure a barra com as palmas voltadas para baixo e as mãos logo acima da largura dos ombros', 'Posicione o tronco e permita que os braços se estendam para a frente sem arredondar excessivamente', 'Puxe os cotovelos para trás e traga a barra ou peso em direção ao tronco', 'Traga os cotovelos para trás sem sacudir o tronco', 'Estenda os braços para a frente novamente sem deixar o tronco balançar']),
  ('X3TCNEU', 'Prancha abdominal suspensa com fita', array['Conecte um treinador suspenso a um ponto de ancoragem alto e ajuste as alças na altura da cintura', 'Fique de costas para o ponto de ancoragem e segure as alças com os braços estendidos à sua frente', 'Aperte o abdômen e mantenha a pelve encaixada antes que os braços se estendam', 'Estenda os braços para a frente mantendo as costelas e a pelve alinhadas e pare antes que a região lombar afunde', 'Pare de estender quando a região lombar começar a afundar', 'Puxe de volta ao início através dos ombros e do abdômen, mantendo a mesma linha corporal']),
  ('x69MAlq', 'Puxada com braços estendidos no cabo', array['Conecte uma barra reta à polia alta de uma máquina de cabo', 'Fique de frente para a máquina em uma postura estável com os pés na largura dos ombros', 'Sente-se erguido e posicione os ombros antes de puxar a barra para baixo', 'Puxe a barra para baixo direcionando os cotovelos em direção às costelas e mantenha o tronco firme', 'Puxe com os cotovelos em vez de se inclinar muito para trás para mover a barra', 'Deixe a barra subir firmemente até que os braços estejam compridos e reinicie os ombros']),
  ('X6C6i5Y', 'Mergulho em paralelas para tríceps no banco', array['Sente-se na borda de um banco ou cadeira com as mãos segurando a borda e os dedos apontando para a frente', 'Afaste o quadril do banco, sustentando seu peso com as mãos', 'Abaixe os ombros e mantenha os cotovelos apontados principalmente para trás', 'Dobre os cotovelos para descer entre os apoios e pare em uma profundidade confortável para os ombros', 'Escolha uma profundidade que permita que os ombros fiquem confortáveis', 'Pressione pelas mãos para subir e reinicie os ombros antes de outra repetição']),
  ('x6KpKpq', 'Flexão de braço com pegada fechada', array['Comece em posição de prancha alta com as mãos posicionadas juntas, diretamente sob os ombros', 'Contraia o tronco e abaixe o corpo em direção ao chão, mantendo os cotovelos próximos aos lados', 'Contraia o abdômen e os glúteos para que os ombros, quadris e tornozelos se movam juntos', 'Dobre os cotovelos para abaixar o peito mantendo o corpo em uma linha reta', 'Mantenha a cabeça alinhada com a coluna enquanto os cotovelos dobram', 'Pressione de volta para os braços estendidos mantendo a linha corporal intacta']),
  ('X6ytgYZ', 'Prancha lateral com halteres e crucifixo invertido', array['Comece deitado de lado com as pernas estendidas e empilhadas uma sobre a outra.', 'Apoie o antebraço no chão diretamente abaixo do ombro, mantendo o cotovelo dobrado em um ângulo de 90 graus.', 'Contraia o abdômen e encontre uma posição que consiga manter sem prender a respiração.', 'Contraia o core e segure a posição enquanto respira normalmente.', 'Continue respirando de forma estável enquanto mantém a mesma linha corporal.', 'Mantenha a forma pelo tempo planejado e saia dela com controle.']),
  ('X7jbxra', 'Alongamento de joelhos em círculos', array['Fique em pé com os pés na largura dos ombros e as mãos nos quadris.', 'Antes de se mover, dobre levemente os joelhos e tire os calcanhares do chão, equilibrando-se na ponta dos pés.', 'Acomode-se na posição inicial e respire calmamente antes de aprofundar o movimento.', 'Vá em direção ao alongamento até sentir uma tensão leve; continue respirando e evite balançar.', 'Permaneça em um alongamento leve em vez de puxar mais com impulso.', 'Mantenha a posição respirando firmemente e depois solte com cuidado; repita do outro lado, se necessário.']),
  ('x825CZm', 'Elevação lateral posterior sentada no cabo', array['Sente-se em um banco de frente para a máquina de cabo com os pés apoiados.', 'Segure as alças do cabo com as palmas voltadas para baixo e estenda os braços retos à sua frente.', 'Comece com uma carga gerenciável e uma pequena flexão nos cotovelos.', 'Eleve os braços para os lados até a altura dos ombros, sem inclinar ou encolher os ombros.', 'Pare perto da altura dos ombros em vez de encolher os ombros para levantar mais alto.', 'Abaixe os braços lentamente para os lados sem balançar o peso.']),
  ('XaaRnRn', 'Flexão inclinada com pegada supina', array['Coloque as mãos na borda de um banco ou superfície elevada, um pouco além da largura dos ombros.', 'Estique as pernas para trás, apoiando-se na ponta dos pés, criando uma linha reta da cabeça aos calcanhares.', 'Contraia o abdômen e os glúteos para que os ombros, quadris e tornozelos se movam juntos.', 'Dobre os cotovelos para abaixar o peito, mantendo o corpo em uma só linha.', 'Mantenha as palmas das mãos na pegada escolhida sem dobrar os pulsos para trás.', 'Empurre de volta para esticar os braços, mantendo a linha corporal intacta.']),
  ('XalXcvM', 'Afundo frontal com halteres e extensão de tríceps', array['Fique em pé com os pés na largura dos ombros, segurando um halter em cada mão.', 'Dê um passo à frente com o pé direito, abaixando o corpo em uma posição de afundo.', 'Posicione a base com largura suficiente para equilibrar antes de dobrar qualquer joelho.', 'Entre no movimento e dobre ambos os joelhos, mantendo o pé da frente apoiado.', 'Mantenha o pé da frente apoiado e evite colapsar para dentro na altura do joelho.', 'Empurre através do pé da frente para retornar ao início e troque de perna conforme planejado.']),
  ('xAySMB0', 'Prancha de equilíbrio', array['Coloque a prancha de equilíbrio em uma superfície plana.', 'Suba na prancha de equilíbrio com um pé, garantindo que esteja centralizado.', 'Contraia o abdômen e encontre uma posição que consiga manter sem prender a respiração.', 'Contraia o core e segure a posição enquanto respira normalmente.', 'Continue respirando de forma estável enquanto mantém a mesma linha corporal.', 'Mantenha a forma pelo tempo planejado e saia dela com controle.']),
  ('xbkPfaw', 'Remada unilateral em pé com o peso corporal', array['Fique em pé com os pés na largura dos ombros, joelhos flexíveis e segure um halter em uma mão.', 'Incline o tronco para a frente a partir dos quadris, com a coluna firme e o core ativado.', 'Posicione o tronco e permita que os braços alcancem a frente sem curvar excessivamente.', 'Puxe os cotovelos para trás e traga a alça ou o peso em direção ao tronco.', 'Mantenha ambos os ombros nivelados e evite virar em direção ao braço que está trabalhando.', 'Estique os braços para a frente novamente sem deixar o tronco balançar; troque de lado quando a série pedir.']),
  ('xBYcQHj', 'Puxada com pegada supinada no cabo', array['Ajuste a máquina de cabo para que a barra de puxada fique em uma altura acima da sua cabeça.', 'Sente-se no assento e segure a barra de puxada com as palmas voltadas para cima, mãos um pouco além da largura dos ombros.', 'Sente-se erguido e alinhe os ombros antes de puxar a alça para baixo.', 'Puxe a alça para baixo direcionando os cotovelos em direção às costelas; mantenha o tronco firme.', 'Puxe com os cotovelos em vez de inclinar muito o tronco para trás para mover a alça.', 'Deixe a alça subir firmemente até que os braços estejam estendidos e redefina a posição dos ombros.']),
  ('xcLntTC', 'Elevação de pernas sentado em banco reto', array['Sente-se em um banco reto com as pernas estendidas para a frente', 'Coloque as mãos no banco ao lado dos quadris para dar suporte', 'Contraia o abdômen e mantenha os ombros firmes no apoio', 'Eleve as pernas contraindo o tronco e movendo os quadris em vez de balançar', 'Desacelere as pernas antes que elas tirem a lombar da posição', 'Abaixe as pernas devagar sem balançar ou perder a posição do tronco']),
  ('Xd65M9w', 'Pullover com halteres em arco', array['Deite-se em um banco com a cabeça em uma extremidade e os pés firmes no chão', 'Segure um halter com as duas mãos e estenda os braços para cima do peito', 'Abaixe as costelas e mantenha uma pequena flexão nos cotovelos antes de descer o peso', 'Abaixe o peso em um arco atrás da cabeça até sentir um  confortável alongamento nos ombros', 'Mantenha as costelas abaixadas enquanto os braços passam por cima da cabeça', 'Puxe o peso de volta sobre o peito pelo mesmo arco, sem levantar as costelas']),
  ('xDh0lJr', 'Desenvolvimento por trás da nuca em pé', array['Fique em pé com os pés na largura dos ombros e segure a barra atrás do pescoço com as palmas voltadas para baixo', 'Mantenha a coluna em uma posição neutra e confortável e o core ativado', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso para cima mantendo o tronco firme', 'Mantenha os punhos alinhados e use um caminho para os ombros que pareça natural', 'Abaixe o peso até a altura inicial de forma controlada antes de empurrar novamente']),
  ('XDOiFns', 'Elevação de panturrilha em pé inclinada no trenó', array['Ajuste a máquina de trenó com um peso confortável e posicione-se com as pontas dos pés na plataforma e os calcanhares para fora', 'Coloque as mãos nos puxadores ou nas laterais da máquina para dar suporte', 'Deixe os tornozelos se moverem livremente enquanto o resto do corpo fica parado', 'Eleve-se na ponta dos pés, levantando os calcanhares o mais alto possível sem balançar', 'Faça uma pausa no topo sem girar os tornozelos para fora', 'Abaixe os calcanhares em um ritmo controlado antes de subir novamente']),
  ('xdYPUtE', 'Sissy squat', array['Fique em pé com os pés na largura dos ombros e as pontas dos pés levemente apontadas para fora', 'Use um objeto estável para manter o equilíbrio se necessário', 'Contraia o abdômen e distribua a pressão por todo o pé', 'Flexione os quadris e os joelhos para descer, mantendo os pés apoiados e os joelhos alinhados com os dedos dos pés', 'Empurre para cima com o peito e os quadris subindo juntos; evite que os joelhos caiam para dentro', 'Fique totalmente em pé, ajuste sua postura e respiração, então inicie a descida seguinte']),
  ('XE93sQZ', 'Rosca concentrada unilateral com halter e apoio', array['Posicione-se em frente a um degrau ou plataforma com um halter em cada mão e as palmas voltadas para o corpo', 'Coloque o pé direito no degrau, garantindo que todo o pé esteja em contato com a superfície', 'Posicione os ombros e a parte superior dos braços antes de flexionar os cotovelos', 'Flexione os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco', 'Mantenha o tronco parado e deixe a flexão do cotovelo levantar o peso', 'Abaixe até que os cotovelos estejam quase retos, mantendo a parte superior dos braços imóvel']),
  ('XeMvLgE', 'Serrote abdominal com roler', array['Comece em posição de prancha com os antebraços no roler e o corpo em linha reta', 'Contraia o tronco e role o roler para a frente de forma controlada, estendendo o corpo o máximo que puder sem perder o controle', 'Aperte o abdômen e mantenha a pelve encaixada antes de afastar os braços', 'Afaste os braços mantendo as costelas e a pelve alinhadas; pare antes que a lombar ceda', 'Pare o movimento quando a lombar começar a ceder', 'Puxe de volta ao início usando os ombros e o abdômen, mantendo a mesma linha corporal']),
  ('XFc3vpY', 'Rosca direta sentado com elástico', array['Sente-se em uma cadeira ou banco com as costas retas e os pés apoiados', 'Segure o elástico de resistência com as palmas voltadas para cima e os braços estendidos para baixo ao lado do corpo', 'Posicione os ombros e a parte superior dos braços antes de flexionar os cotovelos', 'Flexione os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco', 'Controle o elástico na volta em vez de deixar que ele puxe você rapidamente', 'Abaixe até que os cotovelos estejam quase retos, mantendo a parte superior dos braços imóvel']),
  ('xGgAGPm', 'Alongamento de pernas sentado na cadeira', array['Sente-se na borda de uma cadeira com as costas retas e os pés apoiados', 'Estique uma perna para a frente mantendo o calcanhar no chão', 'Ajuste-se na posição inicial e respire calmamente antes de aprofundar', 'Vá em direção ao alongamento até sentir uma tensão leve, continue respirando e evite balançar', 'Mantenha-se em um alongamento leve em vez de puxar mais com impulso', 'Segure a posição com respiração constante e solte devagar, repita do outro lado se necessário']),
  ('xgsGFVM', 'Torção de caranguejo com toque no pé', array['Comece sentado no chão com os joelhos flexionados e os pés apoiados', 'Posicione as mãos atrás de você com os dedos apontando para os pés e eleve os quadris do chão', 'Flexione levemente os joelhos e deixe os quadris iniciarem a dobra', 'Dobre o tronco para a frente a partir dos quadris e leve as mãos em direção aos pés sem forçar o alcance', 'Mantenha o movimento controlado durante toda a amplitude', 'Segure brevemente em uma profundidade confortável e depois suba estendendo os quadris']),
  ('XgWyAiA', 'Mergulho de peito (na estrutura de barra fixa e paralela)', array['Ajuste as barras paralelas a uma altura que permita segurá-las confortavelmente', 'Fique entre as barras e apoie as mãos em cada barra logo acima da largura dos ombros', 'Comece em uma suspensão controlada com os ombros ativos e não relaxados', 'Puxe os cotovelos para baixo e aproxime a parte superior do peito da barra sem chutar as pernas', 'Evite balançar as pernas para passar da barra', 'Desça até esticar os braços sem cair repentinamente do topo']),
  ('XhfS1DZ', 'Alongamento de fibulares', array['Sente-se no chão com as pernas estendidas à sua frente', 'Passe a corda ao redor da sola do pé e segure as pontas da corda com as mãos', 'Ajuste-se na posição inicial e respire calmamente antes de aprofundar', 'Vá em direção ao alongamento até sentir uma tensão leve, continue respirando e evite balançar', 'Mantenha-se em um alongamento leve em vez de puxar mais com impulso', 'Segure a posição com respiração constante e solte devagar, repita do outro lado se necessário']),
  ('xHKN2s8', 'Arranque com barra com um braço', array['Fique em pé com os pés na largura dos ombros e os dedos apontando levemente para fora', 'Segure a barra com as palmas voltadas para baixo e as mãos logo acima da largura dos ombros', 'Contraia o abdômen antes de puxar e mantenha a carga próxima ao corpo', 'Empurre com as pernas e quadris e depois conduza o peso para a posição de recepção', 'Mantenha ambos os ombros nivelados e evite virar o tronco em direção ao braço ativo', 'Fique em pé para finalizar e abaixe o peso de forma controlada antes da próxima repetição, alterne os lados quando necessário']),
  ('xi0yckC', 'Elevação de ombros inclinada com barra', array['Ajuste o banco para aproximadamente 45 graus', 'Sente-se no banco com as costas apoiadas no estofado e os pés firmes no chão', 'Comece com uma carga gerenciável e uma pequena flexão nos cotovelos', 'Eleve os pesos para longe do tronco até a altura dos ombros, mantendo os cotovelos levemente flexionados', 'Pare próximo à altura dos ombros em vez de encolher os ombros para levantar mais alto', 'Abaixe os braços lentamente para as laterais sem balançar o peso']),
  ('xiA6lRr', 'Rosca bíceps sentada com halteres', array['Apoie os dois pés firmes enquanto estiver sentado em um banco e segure um halter em cada mão com as palmas voltadas para cima', 'Mantenha a coluna em uma posição neutra e confortável e os cotovelos próximos ao tronco', 'Posicione os ombros e a parte superior dos braços antes de dobrar os cotovelos', 'Flexione os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco', 'Mantenha o tronco imóvel e use a flexão dos cotovelos para erguer o peso', 'Abaixe até que os braços estejam quase retos, mantendo a parte superior dos braços imóvel']),
  ('xifhB5W', 'Alongamento de deltóide posterior', array['Fique em pé e posicione os pés na largura dos ombros', 'Cruze o braço direito na altura do peito e coloque a mão esquerda no cotovelo direito', 'Ajuste-se na posição inicial e respire calmamente antes de aprofundar', 'Vá em direção ao alongamento até sentir uma tensão leve, continue respirando e evite balançar', 'Mantenha-se em um alongamento leve em vez de puxar mais com impulso', 'Segure a posição com respiração constante e solte devagar, repita do outro lado se necessário']),
  ('XIHEoCG', 'Elevação de panturrilhas em pé', array['Fique em pé com os pés na largura dos ombros e dedos apontados para a frente', 'Antes de se mover, levante os calcanhares do chão o mais alto possível, apoiando-se na ponta dos pés', 'Deixe os tornozelos se moverem livremente enquanto o resto do corpo permanece firme', 'Suba pela parte frontal dos pés, levantando os calcanhares o mais alto que puder sem balançar', 'Faça uma pausa no topo sem girar os tornozelos para fora', 'Abaixe os calcanhares em ritmo controlado antes de subir novamente']),
  ('xiHiJcA', 'Crucifixo inverso na máquina sentado (pegada paralela)', array['Ajuste o assento ao seu corpo e acomode-se na máquina', 'Segure os puxadores com pegada paralela, palmas viradas uma para a outra, e mantenha os braços levemente flexionados', 'Mantenha uma leve flexão nos cotovelos e posicione os ombros antes de mover os braços', 'Abra os braços para fora e para trás com uma leve flexão nos cotovelos, unindo as escápulas', 'Mantenha o ângulo dos cotovelos quase inalterado durante todo o arco', 'Abra os braços de volta pelo mesmo arco sem deixar o peso cair']),
  ('xLYSdtg', 'Crucifixo no cabo', array['Conecte os cabos em ambos os lados de uma polia na altura do peito', 'Posicione-se no centro da máquina com um pé ligeiramente à frente do outro', 'Mantenha uma leve flexão nos cotovelos e posicione os ombros antes de mover os braços', 'Com uma leve flexão nos cotovelos, puxe os braços juntos em um arco amplo', 'Mantenha o ângulo dos cotovelos quase inalterado durante todo o arco', 'Abra os braços de volta pelo mesmo arco sem deixar o peso cair']),
  ('XlZ4lAC', 'Bom dia com barra', array['Comece em pé com os pés na largura dos ombros e a barra apoiada na parte superior das costas', 'Com as costas retas e o abdômen contraído, incline o quadril para a frente, empurrando os glúteos para trás como se quisesse tocar a parede atrás de você', 'Destrave os joelhos e contraia o abdômen antes de mover o quadril para trás', 'Empurre o quadril para trás mantendo a carga próxima e a coluna firme', 'Mantenha o peso próximo às pernas e pare quando as costas começarem a arredondar', 'Empurre o quadril para a frente para ficar erguido sem inclinar o tronco para trás no topo']),
  ('xMjBKwn', 'Elevação lateral a frontal com halteres', array['Fique em pé com os pés na largura dos ombros, segurando um halter em cada mão com as palmas viradas para o corpo', 'Mantenha a coluna em uma posição neutra e confortável e contraia o core', 'Comece com uma carga gerenciável e uma pequena flexão nos cotovelos', 'Levante os braços para a frente até a altura dos ombros, mantendo as costelas para baixo e o tronco imóvel', 'Pare perto da altura dos ombros em vez de encolher os ombros para subir mais', 'Abaixe os braços lentamente para as laterais sem balançar o peso']),
  ('xmM75XG', 'Abdominal supra com carga (na bola suíça)', array['Sente-se em uma bola suíça com os pés apoiados e os joelhos flexionados em um ângulo de 90 graus', 'Pegue uma anilha ou halter com ambas as mãos e estenda os braços acima da cabeça', 'Posicione a pelve e mantenha o pescoço relaxado antes de enrolar o tronco para cima', 'Enrole a caixa torácica em direção à pelve, deixando o abdômen mover o tronco', 'Mantenha a bola firme e use os pés para controlar o seu equilíbrio', 'Abaixe os ombros ou o tronco com controle antes do próximo movimento']),
  ('xmWQIlT', 'Rosca bíceps alternada com halteres sentado na bola de exercício', array['Sente-se em uma bola de exercício com os pés apoiados e as costas retas', 'Segure um halter em cada mão com as palmas viradas para a frente e os braços estendidos', 'Posicione os ombros e a parte superior dos braços antes de flexionar os cotovelos', 'Flexione os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco', 'Termine o movimento de um lado antes que o outro lado comece', 'Abaixe até que os braços estejam quase retos, mantendo a parte superior dos braços imóvel; alterne os lados quando necessário']),
  ('xnInPfE', 'Roda abdominal com barra em pé', array['Fique em pé com os pés na largura dos ombros e segure a barra com ambas as mãos à frente das coxas', 'Contraia o core e, com controle, role a barra para o chão, com a coluna firme e os braços estendidos', 'Aperte o abdômen e mantenha a pelve encaixada antes que os braços se estendam', 'Estique os braços mantendo as costelas e a pelve alinhadas; pare antes que a região lombar ceda', 'Pare de esticar quando a região lombar começar a ceder', 'Puxe de volta para o início usando os ombros e o abdômen, mantendo a mesma linha corporal']),
  ('xNrS20v', 'Rosca inversa com barra', array['Fique em pé com os pés na largura dos ombros e segure uma barra com as palmas voltadas para baixo', 'Deixe os cotovelos se moverem enquanto a parte superior dos braços fica parada, expire e flexione a barra para cima, contraindo os bíceps', 'Posicione os ombros e a parte superior dos braços antes de dobrar os cotovelos', 'Flexione o peso com as palmas voltadas para baixo, mantendo os cotovelos próximos e o tronco parado', 'Mantenha o tronco imóvel e deixe a flexão do cotovelo levantar o peso', 'Abaixe até que os cotovelos estejam quase retos, mantendo a parte superior dos braços parada']),
  ('xo6sENf', 'Elevação de panturrilha na bola suíça na parede', array['Fique em pé com as costas contra a parede e coloque uma bola suíça entre a parte inferior das costas e a parede', 'Posicione os pés na largura dos ombros com os dedos apontados para a frente', 'Deixe os tornozelos se moverem livremente enquanto o resto do corpo permanece imóvel', 'Suba na ponta dos pés, levantando os calcanhares o máximo que puder sem balançar', 'Mantenha a bola firme e use os pés para controlar o equilíbrio', 'Abaixe os calcanhares em um ritmo controlado antes de subir novamente']),
  ('XooAdhl', 'Parada de mãos', array['Escolha um espaço aberto com espaço suficiente para realizar uma parada de mãos', 'Coloque as mãos no chão na largura dos ombros com os dedos apontados para a frente', 'Contraia o abdômen e encontre uma posição que você possa manter sem prender a respiração', 'Contraia a região central do corpo e mantenha a posição respirando normalmente', 'Continue respirando de forma constante enquanto mantém a mesma linha corporal', 'Mantenha a postura pelo tempo planejado e saia dela com controle']),
  ('xOXZJRZ', 'Flexão de braço em relógio', array['Comece em uma posição de prancha alta com as mãos diretamente sob os ombros e o corpo em linha reta', 'Abaixe o corpo em direção ao chão dobrando os cotovelos, mantendo-os próximos às costelas', 'Contraia o abdômen e os glúteos para que os ombros, quadris e tornozelos se movam juntos', 'Dobre os cotovelos para abaixar o peito mantendo o corpo em uma única linha', 'Mantenha a cabeça alinhada com a coluna enquanto os cotovelos dobram', 'Empurre de volta para os braços esticados, mantendo a linha do corpo intacta']),
  ('XPUDTt7', 'Flexão de braço pike para cobra', array['Comece em uma posição de flexão com as mãos logo além da largura dos ombros e os pés juntos', 'Contraia o tronco e levante os quadris em direção ao teto, formando um V invertido com o corpo', 'Contraia o abdômen e os glúteos para que os ombros, quadris e tornozelos se movam juntos', 'Dobre os cotovelos para abaixar o peito mantendo o corpo em uma única linha', 'Mantenha a cabeça alinhada com a coluna enquanto os cotovelos dobram', 'Empurre de volta para os braços esticados, mantendo a linha do corpo intacta']),
  ('XqYQ9JA', 'Rosca martelo unilateral deitado no banco', array['Posicione-se de bruços em um banco plano com um haltere em uma mão, palma voltada para o corpo e braço esticado', 'Mantenha a parte superior do braço parada e flexione o haltere em direção ao ombro, contraindo o bíceps', 'Posicione os ombros e a parte superior dos braços antes de dobrar os cotovelos', 'Flexione com as palmas voltadas uma para a outra e cotovelos próximos às costelas, evite balançar para trás', 'Mantenha ambos os ombros nivelados e evite virar em direção ao braço em movimento', 'Abaixe até que os cotovelos estejam quase retos, mantendo a parte superior dos braços parada e alterne os lados quando necessário']),
  ('XsCcxCC', 'Good morning sentado na máquina', array['Ajuste a altura do assento para que seus quadris fiquem ligeiramente mais altos que os joelhos', 'Sente-se na máquina com as costas apoiadas no encosto e os pés apoiados nos suportes', 'Destrave os joelhos e contraia o abdômen antes de mover os quadris para trás', 'Empurre os quadris para trás mantendo a carga próxima e a coluna firme', 'Mantenha o peso próximo às pernas e pare quando as costas começarem a curvar', 'Empurre os quadris para a frente para ficar em pé sem inclinar para trás no topo']),
  ('XSCHmiI', 'Elíptico', array['Ajuste o assento ao seu corpo e acomode-se na máquina', 'Coloque os pés nos pedais e segure os guidões', 'Comece em um ritmo que permita aos pés e braços se moverem em sincronia', 'Mova-se em um ritmo repetível, mantendo o movimento suave e a respiração constante', 'Mantenha o padrão repetível conforme a velocidade aumenta', 'Mantenha o ritmo pelo intervalo planejado, diminuindo a velocidade se a postura começar a falhar']),
  ('xTjr103', 'Alongamento em pé para posteriores e panturrilha com faixa', array['Fique em pé com os pés na largura dos ombros', 'Segure a faixa com ambas as mãos e coloque-a na planta do pé', 'Adote a posição inicial e respire calmamente antes de aprofundar o movimento', 'Abaixe o calcanhar e desloque até esticar a panturrilha mantendo o pé apontado para frente', 'Mantenha um alongamento leve em vez de puxar com impulso', 'Segure a posição com respiração constante e solte devagar repita do outro lado se necessário']),
