  ('zhMwOwE', 'Extensão lombar', array['Ajuste o banco de extensão lombar para que suas coxas fiquem apoiadas no suporte e os pés presos', 'Cruze os braços sobre o peito ou coloque as mãos atrás da cabeça', 'Fixe os quadris e os pés no suporte antes de levantar', 'Eleve o tronco ou as pernas até alinharem com o corpo, sem arquear excessivamente a região lombar', 'Finalize com o corpo em linha reta, antes que a lombar arqueie demais', 'Traga o peso ou o corpo de volta à posição inicial sem pressa']),
  ('ziFKQXP', 'Tríceps francês com halter em apoio unilateral (na bola suíça)', array['Sente-se em uma bola suíça com os pés apoiados e as costas retas', 'Segure um halter em uma mão com a palma virada para cima e o cotovelo dobrado em um ângulo de 90 graus', 'Posicione os braços firmemente antes de estender os cotovelos', 'Dobre os cotovelos para descer a barra atrás da cabeça enquanto os braços permanecem praticamente parados', 'Mantenha ambos os ombros nivelados e evite girar o corpo em direção ao braço que está trabalhando', 'Estique os cotovelos para erguer a barra acima da cabeça, inicie a próxima repetição controlada e troque de lado quando necessário']),
  ('zILLZ98', 'Rosca direta com pegada inversa no Smith', array['Ajuste a altura da barra do Smith na altura da cintura', 'Posicione-se de frente para a máquina em uma base estável com os pés na largura dos ombros', 'Posicione os ombros e os braços antes de dobrar os cotovelos', 'Dobre os cotovelos para aproximar o peso dos ombros sem balançar o tronco', 'Mantenha o tronco imóvel e use a flexão do cotovelo para levantar o peso', 'Desça até que os cotovelos estejam quase esticados, mantendo a parte superior dos braços parada']),
  ('ZIViNh1', 'Remada unilateral com halter no banco inclinado e pegada inversa', array['Ajuste o banco para aproximadamente 45 graus', 'Coloque um halter no chão ao lado do banco', 'Posicione o tronco e permita que os braços estique para a frente sem arredondar excessivamente', 'Puxe os cotovelos para trás e traga a alça ou o peso em direção ao tronco', 'Mantenha ambos os ombros nivelados e evite girar em direção ao braço em movimento', 'Estique os braços novamente para a frente sem deixar o tronco balançar e troque de lado quando necessário']),
  ('zK8Fu1W', 'Supino com pegada inversa no Smith', array['Ajuste a altura da barra do Smith na altura do peito', 'Posicione-se de frente para a barra em uma base estável com os pés na largura dos ombros', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso para longe enquanto mantém o tronco firme', 'Mantenha as palmas das mãos na pegada escolhida sem dobrar os punhos para trás', 'Desça o peso até a altura inicial de forma controlada antes de empurrar novamente']),
